const res = $json;
const meetingId = $('MoM Trigger').item.json.body.meeting_id || 'bbbbbbb2-bbbb-bbbb-bbbb-bbbbbbbbbbbb';

// Выделение Action Items
const actionItems = [
  {
    action_id: 'eeeeeee1-eeee-eeee-eeee-eeeeeeeeeeee',
    title: 'Сформировать и отправить поставщику спецификацию на валы Heidelberg',
    responsible: 'Иван Кузнецов (Начальник производства)',
    responsible_id: 2,
    deadline: 'через 2 дня'
  },
  {
    action_id: 'eeeeeee2-eeee-eeee-eeee-eeeeeeeeeeee',
    title: 'Оплатить счет на запчасти Heidelberg (аванс 50%)',
    responsible: 'Ольга Соколова (Главный бухгалтер)',
    responsible_id: 4,
    deadline: 'через 3 дня'
  }
];

const msgText = `📋 Сформирован протокол встречи (MoM)\n\n` +
  `📁 Файл протокола сгенерирован в формате Word (.docx).\n\n` +
  `🎯 Выделены поручения (требуется подтверждение постановки в Битрикс24):\n` +
  actionItems.map((a, i) => `${i+1}. ${a.title}\n   👤 Ответственный: ${a.responsible}\n   ⏳ Срок: ${a.deadline}`).join('\n\n');

const inlineKeyboard = actionItems.map(a => ([
  {
    text: `✅ Поставить в Битрикс: "${a.title.substring(0, 30)}..."`,
    callback_data: `create_bitrix_task:${a.action_id}`
  }
]));

return [{
  json: {
    status: 'success',
    protocol_id: res.protocol_id,
    meeting_id: meetingId,
    message_markdown: msgText,
    inline_keyboard: inlineKeyboard,
    action_items: actionItems,
    docx_ready: true
  }
}];
